UPDATE iam_user_account
SET org_id = #{orgId}, email = #{email}, phone = #{phone}, password_hash = #{passwordHash},
    enabled = #{enabled}, status = #{status}, last_login = #{lastLogin}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND user_id = #{userId}

